export class YandexMap{constructor(){this.boxes=document.querySelectorAll("[data-map]"),this.boxes.length&&this.init()}init(){this.boxes.forEach(e=>{const t=e.querySelector("[data-map-load]");t&&t.addEventListener("click",()=>{const a=document.createElement("iframe");a.src=e.dataset.map,a.title="Карта: как нас найти",a.loading="lazy",a.allowFullscreen=!0,e.appendChild(a),t.remove()})})}}